// Study Cards: the shop's loot. Shared by the site (/shop, the dashboard player card) and the API (/pack, /loadout,
// the Discord card images). Every pack draws from all of ITEMS: three cards, odds per card in ODDS, the third card is
// always Uncommon or better. A duplicate pays back REFUND (a third of the pack price x 0.2 / 0.4 / 1.2 / 3.0).
// Looks: site CSS is cosmetics.css (pfp borders .cb-<key>, bars .cbar-<key>); the Discord images use LOOK below
// (satori can't draw the CSS ones, so those are simpler versions with the same colours).
export const PRICE = 100;
export const TIERS = ['Common', 'Uncommon', 'Rare', 'Epic'];
export const ODDS = { Common: 55, Uncommon: 30, Rare: 11, Epic: 4 };
export const REFUND = { Common: 7, Uncommon: 13, Rare: 40, Epic: 100 };
export const TCOL = { Common: '#a9a3c9', Uncommon: '#8fe0b0', Rare: '#e0507f', Epic: '#f0c75e' };
export const SLOT_NAMES = ['Title', 'Pfp border', 'Overall bar', 'Sticker'];
const L = s => s.split('|').map(n => [n]);
const SLOTS = {
 'Title':{
  Common:L("The Fish|Short Stack|Limper|Nit|The Grinder|River Rat|Big Blind|Night Owl|Small Blind|Under the Gun|The Cutoff|The Button|Pocket Pair|Suited Connector|Offsuit|Top Pair|Overpair|Kicker Trouble|Gutshot|Open Ender|Set Miner|Flush Chaser|Straight Shooter|The Rock|Min Raiser|Three Bettor|Check Raiser|Value Bettor|Pot Builder|Chip Stacker|Chip Counter|Deep Stack|Blind Defender|Pot Committed|Heads Up|Late Arrival|Early Bird|Table Talker|The Regular|Cash Gamer|Ante Up|Dealer's Choice|Fold Pre|Rookie|Tourney Regular"),
  Uncommon:L("Calling Station|Card Dead|Bubble Boy|Chip Leaker|Bluff Master|Rebuy King|The Professor|The Closer|Giant Killer|Slow Player|Hero Caller|Snap Caller|Float Master|Overbetter|Donk Bettor|The Tank|Clock Watcher|Chip Magnet|Run Good|Splash Pot|Bad Beat Story|Rail Coach|Cooler Magnet|Second Best|Bubble Survivor|Final Table|Heads Up Hero|Muck Master|Late Reg|Rebuy Regular|Teacher's Pet|Honor Roll|Hall Monitor|Extra Credit|Class Clown|Mr. Hollywood|Pot Odds Nerd|Hand Reader"),
  Rare:L("Donkey|Tilt Machine|ATM|Coin Flip Merchant|Fish Food|Whale Watcher|Bad Beat Magnet|Lucky Idiot|Paid Off|The Cooler|Bubble Buster|Cash Cow|Free Money|Suited Garbage|Never Folds|Raise Everything|Shove Monkey|Tilt Warrior"),
  Epic:L("Cringe Lord|The Shark|The Legend|Down Bad|Professional Loser|Rigged|Unbluffable|The Final Boss|Generational Punt|Absolutely Cooked|Valedictorian")},
 'Pfp border':{Common:[['Chalk','chalk'],['Felt','felt'],['Cardboard','cardboard'],['Pencil','pencil'],['Fish Tank','fish'],['Paper Card','paper'],['Matchbook','match'],['Cozy Night','cozy'],['Petri Dish','petri'],['Small Blind','sb'],['Under the Gun','utg'],['Brushed Brass','brass'],['Pixel Checker','checker']],Uncommon:[['Neon','neon'],['Bad Beat','beat'],['Dealer Button','dealer'],['Garden Party','garden'],['Ticker Tape','ticker'],['Big Blind','bb'],['Cutoff','co'],['Lojack','lj'],['Hijack','hj'],['Graph Paper','graph'],['Censored Bar','censored'],['CRT Scanlines','crt'],['Camera Viewfinder','finder']],Rare:[['Flames','flame'],['Snake Eyes','snake'],['Soul','soul'],['Breaking News','news'],['The Button','btn'],['Straddle','str'],['Rainy Window','rain'],['Frostbite','frost']],Epic:[['Lightning','lightning'],['Holo Joker','holojoker'],['Matrix Rain','matrix']]},
 'Overall bar':{Common:[['Maroon','maroon'],['Felt Green','felt'],['Slate','slate'],['Navy','navy'],['Charcoal','charcoal'],['Plum','plum'],['Mustard','mustard'],['Teal','teal'],['Paper Card','paper'],['Matchbook','match'],['Cozy Night','cozy']],Uncommon:[['Ice','ice'],['Sunset','sunset'],['Mint','mint'],['Bad Beat','beat'],['Neon Sign','neonsign'],['Dealer Button','dealer']],Rare:[['Black Gold','black'],['Ruby','ruby'],['Soul','soul']],Epic:[['Holo','holo']]},
 'Sticker':{Common:L("Fish|Spade|Heart|Dice|Pizza Slice|Coffee|Night Owl Moon|Lucky Clover|Poker Chip|Sunglasses|The Nuts|Diamond|Cocktail|Donkey"),Uncommon:L("Dealer Button|Bad Beat|Rebuy Ticket|Trophy|Money Bag|On Fire|Ice Cold|Tanking|Ship It|Rivered|Tilted|Last Call|Slow Roll|Chop Pot"),Rare:L("All In|Pocket Aces|Royal Flush"),Epic:L("Crown|Shark|Snowed In")}
};
const slug = n => n.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const CODE = { 'Title': 't', 'Pfp border': 'b', 'Overall bar': 'o', 'Sticker': 's' };
/** every item: { id: 't:coin-flip-merchant', slot, tier, name, key } (key = the CSS class part for borders and bars) */
const ALL = [];
for (const slot of SLOT_NAMES) for (const tier of TIERS) for (const [name, key] of SLOTS[slot][tier]) ALL.push({ id: CODE[slot] + ':' + (key || slug(name)), slot, tier, name, key: key || slug(name) });
/** items taken out of the game: no longer in packs, the loadout or on cards. Whoever owned one gets its duplicate refund
 *  (once, see loadout() in _shop.js). b:dealer = Dealer Button border, removed 2026-11-18 (The Button already has the D) */
export const RETIRED = ['b:dealer', 't:bubble-boy']; // t:bubble-boy became the earned poker title Bubble Boy (a:bubble)
/** the items in play (packs, loadout, collection counts) */
export const ITEMS = ALL.filter(i => !RETIRED.includes(i.id));
/** every item by id, retired ones too, so old pack messages still read */
export const BY_ID = Object.fromEntries(ALL.map(i => [i.id, i]));
export const byName = (slot, name) => ITEMS.find(i => i.slot === slot && i.name === name);
const BY_TIER = Object.fromEntries(TIERS.map(t => [t, ITEMS.filter(i => i.tier === t)]));
/** rand() returns [0, 1). Card 1 and 2 use ODDS, card 3 skips Common. */
export function rollTier(rand, upOnly = false) {
  const r = rand() * (upOnly ? 45 : 100) + (upOnly ? 55 : 0);
  return r < 55 ? 'Common' : r < 85 ? 'Uncommon' : r < 96 ? 'Rare' : 'Epic';
}
export const rollItem = (rand, upOnly) => { const pool = BY_TIER[rollTier(rand, upOnly)]; return pool[Math.floor(rand() * pool.length)]; };
export const rollPack = rand => [rollItem(rand), rollItem(rand), rollItem(rand, true)];

/** pack art: the pack design shown on the wrapper (random per pack, contents are the same) */
