export const decoFor = it => !it ? '' : it.tier === 'Champion' ? champDeco(it) : it.tier === 'Earned' ? accDeco(it) : DECO[it.key] || '';
/** any border's Discord-image look override (champion and accolade borders), or null for pack borders (LOOK.border) */
export const lookFor = it => !it ? null : it.tier === 'Champion' ? champLook(it) : it.tier === 'Earned' ? accLook(it) : null;
/** the short note shown under an item in the loadout: how it was earned (champion + accolades) or its rarity */
export const noteFor = it => it.why || it.tier;
